/**
 * The conformance runner — a **fake runtime** replays the golden traces
 * `conformance/traces/*.json` into the real SDK, over real HTTP (`serve()`: h1 for
 * `REQUEST_RESPONSE`, h2c cho `BIDI_STREAM`).
 *
 * The traces are generated by `crates/cairn-runtime/tests/conformance_gen.rs` from
 * the runtime's real state machine and a reference SDK encoding with `prost`. Every
 * SDK → runtime frame is compared **byte for byte** (the trace's `match` says where
 * it is relaxed) — so this is also the check of the hand-written protobuf codec
 * (`src/protobuf.ts`, `src/wire.ts`) against the `.proto`. The runner's rules live in
 * `conformance/README.md`; this file is the TypeScript implementation of exactly
 * those rules, and deliberately does **not** use the SDK's codec to read frames
 * (header and varint are read by hand), so the codec is not checked against itself.
 *
 * Each trace runs twice when `wire_version` < 3: the SDK left as is (a runtime older
 * than the SDK) and the SDK pinned at `maxProtocolVersion = wire_version` (an SDK
 * older than the runtime) — two negotiations arriving at the same version.
 *
 * `REQUEST_RESPONSE` traces also run through the **Fetch adapter** (`fetchHandler`)
 * mounted under the `/cairn` prefix behind a `node:http` bridge
 * (`fetch-bridge.ts`) — same bytes, same rules.
 */

import assert from "node:assert/strict";
import { readdirSync, readFileSync } from "node:fs";
import * as http2 from "node:http2";
import { after, test } from "node:test";
import {
  type Context,
  type Endpoint,
  MAX_PROTOCOL_VERSION,
  type ProtocolMode,
  serve,
  service,
} from "../src/index.ts";
import { fetchHandler } from "../src/fetch.ts";
import { treeSatisfied } from "../src/handler.ts";
import { encodeSuspensionSpec, type SuspensionTree } from "../src/wire.ts";
import { bridge } from "./fetch-bridge.ts";
import { signer } from "./signer.ts";

// ─────────────────────────────────────────────────────────── traces

interface TraceFrame {
  readonly from: "runtime" | "sdk";
  readonly channel: "journal" | "side";
  readonly type: string;
  readonly name: string;
  readonly flags: string;
  readonly hex: string;
  readonly match?: "bytes" | "type" | "error";
  readonly error_code?: number;
  readonly error_behavior?: number;
  readonly summary: string;
}

interface Connection {
  readonly verify: boolean;
  readonly close: "sdk" | "runtime";
  /** A version-too-new trace: the SDK must refuse the connection with this code, no frames. */
  readonly status?: number;
  /** Wire v5 (`protocol-v1.md` §9.3), v5 traces only — `conformance/README.md`, incremental replay. */
  readonly replay?: {
    readonly sdk_restart?: boolean;
    readonly miss?: boolean;
    readonly cache?: number;
    readonly stale_sdk?: boolean;
    readonly held?: number;
    readonly held_digest?: string;
  };
  readonly frames: readonly TraceFrame[];
}

interface JournalEntry {
  readonly index: number;
  readonly type: string;
  readonly name: string;
  readonly payload_hex: string;
  readonly match?: "bytes" | "type";
  readonly summary: string;
}

interface Trace {
  readonly format: string;
  readonly name: string;
  /** A wire v6 trace: segments the runner serves by URL. */
  readonly segments?: ReadonlyArray<{ readonly url: string; readonly hex: string }>;
  /** A version-too-new trace: the pinned SDK cap, lower than `wire_version`. */
  readonly sdk_max_protocol_version?: number;
  readonly matrix_cells: readonly number[];
  readonly wire_version: number;
  readonly mode: ProtocolMode;
  readonly handler: { readonly service: string; readonly name: string };
  readonly clock_ms: number;
  readonly initial_journal_len: number;
  readonly connections: readonly Connection[];
  readonly journal: readonly JournalEntry[];
}

const ROOT = new URL("../../../conformance/", import.meta.url);
const schema = JSON.parse(readFileSync(new URL("trace.schema.json", ROOT), "utf8")) as Schema;
const traceFiles = readdirSync(new URL("traces/", ROOT))
  .filter((f) => f.endsWith(".json"))
  .sort();

// ─────────────────────────────── schema check (a sufficient subset of JSON Schema)

interface Schema {
  readonly $ref?: string;
  readonly type?: string;
  readonly const?: unknown;
  readonly enum?: readonly unknown[];
  readonly pattern?: string;
  readonly minimum?: number;
  readonly required?: readonly string[];
  readonly properties?: Readonly<Record<string, Schema>>;
  readonly additionalProperties?: boolean;
  readonly items?: Schema;
  readonly $defs?: Readonly<Record<string, Schema>>;
}

function validate(value: unknown, s: Schema, path: string, out: string[]): void {
  if (s.$ref !== undefined) {
    const def = schema.$defs?.[s.$ref.replace("#/$defs/", "")];
    if (def === undefined) throw new Error(`schema lacks ${s.$ref}`);
    validate(value, def, path, out);
  }
  if (s.const !== undefined && value !== s.const) out.push(`${path}: must be ${JSON.stringify(s.const)}`);
  if (s.enum !== undefined && !s.enum.includes(value)) out.push(`${path}: outside ${JSON.stringify(s.enum)}`);
  switch (s.type) {
    case "object": {
      if (typeof value !== "object" || value === null || Array.isArray(value)) {
        out.push(`${path}: not an object`);
        return;
      }
      const o = value as Record<string, unknown>;
      for (const k of s.required ?? []) if (!(k in o)) out.push(`${path}: missing ${k}`);
      for (const [k, v] of Object.entries(o)) {
        const p = s.properties?.[k];
        if (p !== undefined) validate(v, p, `${path}.${k}`, out);
        else if (s.additionalProperties === false) out.push(`${path}: unknown key ${k}`);
      }
      return;
    }
    case "array":
      if (!Array.isArray(value)) {
        out.push(`${path}: not an array`);
        return;
      }
      if (s.items !== undefined) value.forEach((v, i) => validate(v, s.items!, `${path}[${i}]`, out));
      return;
    case "string":
      if (typeof value !== "string") out.push(`${path}: not a string`);
      else if (s.pattern !== undefined && !new RegExp(s.pattern).test(value)) {
        out.push(`${path}: pattern mismatch ${s.pattern}`);
      }
      return;
    case "integer":
      if (!Number.isInteger(value)) out.push(`${path}: not an integer`);
      else if (s.minimum !== undefined && (value as number) < s.minimum) out.push(`${path}: < ${s.minimum}`);
      return;
    case "boolean":
      if (typeof value !== "boolean") out.push(`${path}: not a boolean`);
      return;
    default:
      return;
  }
}

// ─────────────────────────────────────────────────── handler conformance

/** The `slowRun` closure: the runner releases it when it sees the first `Keepalive`. */
let releaseSlow: (() => void) | null = null;

/**
 * The conformance handlers — **same names, same behaviour** as the reference SDK's
 * `Program` (`crates/cairn-runtime/tests/conformance/scenarios.rs`) and the table in
 * `conformance/README.md` §Handler.
 */
const conformance = service(
  "Conformance",
  {
    async counter(ctx: Context) {
      const n = await ctx.get<number>("count");
      await ctx.sleep(1000);
      await ctx.run("charge", () => "charged");
      ctx.set("count", (n ?? 0) + 1);
      return "done";
    },
    async counterRenamed(ctx: Context) {
      const n = await ctx.get<number>("count");
      await ctx.sleep(1000);
      await ctx.run("charge-v2", () => "charged");
      ctx.set("count", (n ?? 0) + 1);
      return "done";
    },
    async counterChanged(ctx: Context) {
      await ctx.get<number>("count");
      ctx.set("count", 9);
      return "other";
    },
    async outOfOrder(ctx: Context) {
      const a = ctx.sleep(1000);
      const b = ctx.sleep(2000);
      await a;
      await b;
      return "both";
    },
    async sleepRunSleep(ctx: Context) {
      const a = ctx.sleep(1000);
      const b = ctx.sleep(2000);
      await ctx.run("pay", () => "result");
      await a;
      await b;
      return "done";
    },
    async eagerCount(ctx: Context) {
      const n = await ctx.get<number>("count");
      ctx.set("count", (n ?? 0) + 1);
      return "done";
    },
    async stateKeys(ctx: Context) {
      return await ctx.getKeys();
    },
    async promise(ctx: Context) {
      await ctx.promise<string>("approve").resolve("ok");
      return await ctx.promise<string>("approve").get();
    },
    async raceSignal(ctx: Context) {
      const v = await ctx.race([ctx.sleep(60_000), ctx.signal<string>("approve")]);
      return v === undefined ? "sleep" : v;
    },
    async raceAwakeable(ctx: Context) {
      const { promise } = ctx.awakeable<string>();
      const v = await ctx.race([promise, ctx.sleep(60_000)]);
      return v === undefined ? "sleep" : v;
    },
    async allSignal(ctx: Context) {
      const [, s] = await ctx.all([ctx.sleep(1000), ctx.signal<number>(4)]);
      return s;
    },
    async allOf(ctx: Context) {
      const a = ctx.sleep(1000);
      const b = ctx.sleep(2000);
      await ctx.all([a, b]);
      return "both";
    },
    async scopedCall(ctx: Context) {
      return await ctx.scoped("tenant-a", "k1").call<number>("Callee", "work", 1);
    },
    async spreadCall(ctx: Context) {
      return await ctx.call<number>("Callee", "work", 1, { placement: "spread" });
    },
    async streamRun(ctx: Context) {
      const ui = ctx.stream("ui");
      await ctx.run("llm", () => {
        ui.append({ tok: "a" });
        ui.append({ tok: "b" });
        return "ab";
      });
      return "done";
    },
    async parallelBranches(ctx: Context) {
      const branch = async (n: string) => [
        await ctx.run(`${n}1`, () => `${n}1`),
        await ctx.run(`${n}2`, () => `${n}2`),
      ];
      return await Promise.all([branch("a"), branch("b")]);
    },
    async callRetargeted(ctx: Context) {
      await ctx.call("Callee", "b", 1);
      return "x";
    },
    async stateKeyChanged(ctx: Context) {
      await ctx.get("total");
      return "x";
    },
    async segmentedGet(ctx: Context) {
      return await ctx.get<string>("history");
    },
    async segmentedSetReuseTail(ctx: Context) {
      const h = await ctx.get<string>("history");
      ctx.set("history", `${h}b`);
      return "ok";
    },
    async segmentedRunResult(ctx: Context) {
      const h = await ctx.get<string>("history");
      await ctx.run("extend", () => `${h}c`);
      return "ok";
    },
    async slowRun(ctx: Context) {
      return await ctx.run(
        "slow",
        () =>
          new Promise<string>((resolve) => {
            releaseSlow = () => resolve("done");
          }),
      );
    },
  },
  { type: "VIRTUAL_OBJECT" },
);

// ─────────────────────────────────────────────────── the SDK endpoint

const endpoints = new Map<string, Promise<Endpoint>>();

/** `via`: the real `serve()`, or the Fetch adapter behind a `node:http` bridge. */
type Via = "serve" | "fetch";

/**
 * The fake runtime signs every request, as the real one does: the replay cache (wire v5) is
 * only served by an endpoint with `identityKeys`, wire v6 by one with `identityKeys` or
 * `segmentOrigins`. `REQUEST_RESPONSE` endpoints verify identity; `BIDI_STREAM` ones (no replay
 * cache) list `segmentOrigins` instead — under the trace's fixed clock two connections of one
 * invocation carry byte-identical JWTs, and a BIDI endpoint opens a stream once per JWT.
 */
const rt = await signer();

/** Identity headers for a request to `url` (its path is the JWT `aud`), opening with `body`. */
function signed(url: string, body?: Uint8Array): Promise<Record<string, string>> {
  return rt.headers(new URL(url).pathname, body);
}

function freshEndpoint(mode: ProtocolMode, maxWire: number, via: Via): Promise<Endpoint> {
  // The replay cache (wire v5) is on in both paths: `serve()` enables it by default with
  // `identityKeys`, the Fetch adapter disables it by default so v5 traces enable it explicitly.
  const fetchOpts = { services: [conformance], maxProtocolVersion: maxWire, replayCache: true, identityKeys: [rt.kid] };
  // BIDI: no identity, so wire v6 needs `segmentOrigins` — the origins the traces' segments come from.
  const segmentOrigins = [...new Set(traces.flatMap((t) => (t.segments ?? []).map((s) => new URL(s.url).origin)))];
  const identity = mode === "REQUEST_RESPONSE" ? { identityKeys: [rt.kid] } : { segmentOrigins };
  return via === "serve"
    ? serve({ services: [conformance], port: 0, protocolMode: mode, maxProtocolVersion: maxWire, ...identity })
    : bridge("fetch", fetchHandler(fetchOpts)).then((b) => ({
        port: 0,
        url: `${b.origin}/cairn`,
        close: () => b.close(),
      }));
}

function endpoint(mode: ProtocolMode, maxWire: number, via: Via): Promise<Endpoint> {
  const k = `${mode}/${maxWire}/${via}`;
  let ep = endpoints.get(k);
  if (ep === undefined) {
    ep = freshEndpoint(mode, maxWire, via);
    endpoints.set(k, ep);
  }
  return ep;
}

after(async () => {
  for (const ep of endpoints.values()) await (await ep).close();
});

// ─────────────────────────────────────── frames — read independently of the SDK codec

interface RawFrame {
  readonly type: number;
  readonly flags: number;
  readonly bytes: Uint8Array;
}

function hexOf(b: Uint8Array): string {
  return Buffer.from(b).toString("hex");
}

function fromHex(h: string): Uint8Array {
  return new Uint8Array(Buffer.from(h, "hex"));
}

/** Splits the byte stream into frames: an 8-byte big-endian header (type u16, flags u16, length u32). */
class Splitter {
  private buf: Uint8Array = new Uint8Array();

  push(chunk: Uint8Array): RawFrame[] {
    const joined = new Uint8Array(this.buf.length + chunk.length);
    joined.set(this.buf);
    joined.set(chunk, this.buf.length);
    const out: RawFrame[] = [];
    let at = 0;
    for (;;) {
      if (joined.length - at < 8) break;
      const v = new DataView(joined.buffer, joined.byteOffset + at, 8);
      const len = v.getUint32(4);
      if (joined.length - at < 8 + len) break;
      out.push({ type: v.getUint16(0), flags: v.getUint16(2), bytes: joined.slice(at, at + 8 + len) });
      at += 8 + len;
    }
    this.buf = joined.slice(at);
    return out;
  }

  get pending(): number {
    return this.buf.length;
  }
}

/** The side channel (`protocol-v1.md` §9.2): `Keepalive` and the custom `0xFC00+` range. */
function isSide(type: number): boolean {
  // Keepalive (v3), StreamAppend and ArtifactPut (v4), the custom range.
  return type === 0x0008 || type === 0x000b || type === 0x000c || type >= 0xfc00;
}

/** Reads the varint of top-level field `n` of a protobuf payload (0 if absent). */
function varintField(payload: Uint8Array, n: number): number {
  let at = 0;
  const varint = (): number => {
    let r = 0;
    let shift = 1;
    for (;;) {
      const b = payload[at++]!;
      r += (b & 0x7f) * shift;
      if ((b & 0x80) === 0) return r;
      shift *= 128;
    }
  };
  let found = 0;
  while (at < payload.length) {
    const key = varint();
    const field = Math.floor(key / 8);
    switch (key & 7) {
      case 0: {
        const v = varint();
        if (field === n) found = v;
        break;
      }
      case 2: {
        // Two lines, not `at += varint()`: the left side reads `at` BEFORE varint moves it.
        const len = varint();
        at += len;
        break;
      }
      case 1:
        at += 8;
        break;
      case 5:
        at += 4;
        break;
      default:
        throw new Error(`unknown wire type ${key & 7}`);
    }
  }
  return found;
}

function describe(f: RawFrame): string {
  return `0x${f.type.toString(16).padStart(4, "0")} flags=0x${f.flags.toString(16)} ${hexOf(f.bytes)}`;
}

/** Compares an SDK frame with the trace per `match`. `null` = match, a string = why it differs. */
function mismatch(want: TraceFrame, got: RawFrame): string | null {
  const head = hexOf(got.bytes.subarray(0, 4));
  switch (want.match ?? "bytes") {
    case "bytes":
      return hexOf(got.bytes) === want.hex ? null : "bytes differ";
    case "type":
      return head === want.hex.slice(0, 8) ? null : "type/flags differ";
    case "error": {
      if (head !== want.hex.slice(0, 8)) return "type/flags differ";
      const payload = got.bytes.subarray(8);
      const code = varintField(payload, 1);
      const behavior = varintField(payload, 9);
      return code === want.error_code && behavior === want.error_behavior
        ? null
        : `ErrorMessage code=${code} behavior=${behavior}, the trace demands code=${want.error_code} behavior=${want.error_behavior}`;
    }
  }
}

/** SDK → runtime frames in arrival order, with waiting. */
class Inbox {
  private readonly queue: RawFrame[] = [];
  private readonly split = new Splitter();
  private waiter: (() => void) | null = null;
  ended = false;

  push(chunk: Uint8Array): void {
    this.queue.push(...this.split.push(chunk));
    this.wake();
  }

  end(): void {
    this.ended = true;
    this.wake();
  }

  private wake(): void {
    const w = this.waiter;
    this.waiter = null;
    w?.();
  }

  async next(what: string): Promise<RawFrame | null> {
    const deadline = performance.now() + 5_000;
    for (;;) {
      const f = this.queue.shift();
      if (f !== undefined) return f;
      if (this.ended) return null;
      const left = deadline - performance.now();
      if (left <= 0) throw new Error(`SDK silent for over 5 s while the runner waits for ${what}`);
      await new Promise<void>((resolve) => {
        const t = setTimeout(resolve, left);
        this.waiter = () => {
          clearTimeout(t);
          resolve();
        };
      });
    }
  }

  /** Frames left after the SDK closes — only side-channel frames are allowed. */
  async rest(): Promise<RawFrame[]> {
    const out: RawFrame[] = [];
    for (;;) {
      const f = await this.next("the SDK closing its side");
      if (f === null) break;
      out.push(f);
    }
    assert.equal(this.split.pending, 0, "half a frame left at the end of the SDK stream");
    return out.filter((f) => !isSide(f.type));
  }
}

/**
 * Reads the next SDK frame and compares it with `want`. Side-channel frames not in
 * the trace (extra `Keepalive`s — their number is decided by timing) are skipped.
 */
async function expectSdk(inbox: Inbox, want: TraceFrame, at: string): Promise<RawFrame> {
  for (;;) {
    const got = await inbox.next(`${want.name} (${at})`);
    if (got === null) assert.fail(`${at}: the SDK closed, the trace still expects ${want.name}: ${want.summary}`);
    const why = mismatch(want, got);
    if (why === null) return got;
    if (isSide(got.type) && !(want.channel === "side" && got.type === Number(want.type))) continue;
    assert.fail(`${at}: ${why}\n  trace: ${want.name} ${want.hex}\n       ${want.summary}\n  SDK:  ${describe(got)}`);
  }
}

/** Gathers consecutive runtime frames into one write — as a real runtime flushes a batch. */
function runs(frames: readonly TraceFrame[]): Array<{ from: "runtime"; bytes: Uint8Array } | TraceFrame> {
  const out: Array<{ from: "runtime"; bytes: Uint8Array } | TraceFrame> = [];
  let batch: Uint8Array[] = [];
  const flush = (): void => {
    if (batch.length > 0) out.push({ from: "runtime", bytes: Buffer.concat(batch) });
    batch = [];
  };
  for (const f of frames) {
    if (f.from === "runtime") batch.push(fromHex(f.hex));
    else {
      flush();
      out.push(f);
    }
  }
  flush();
  return out;
}

const INVOCATION = /^application\/vnd\.cairnflow\.invocation\.v(\d+)$/;

function checkContentType(ct: string | undefined, wire: number, at: string): void {
  const m = INVOCATION.exec((ct ?? "").split(";")[0]!.trim());
  assert.ok(m !== null && Number(m[1]) <= wire, `${at}: response content-type ${ct}`);
}

// ─────────────────────────────────────────────────── running one trace

async function requestResponse(ep: Endpoint, t: Trace, conn: Connection, at: string): Promise<void> {
  const body = Buffer.concat(conn.frames.filter((f) => f.from === "runtime").map((f) => fromHex(f.hex)));
  const ct = `application/vnd.cairnflow.invocation.v${t.wire_version}`;
  const url = `${ep.url}/invoke/${t.handler.service}/${t.handler.name}`;
  const r = await fetch(url, {
    method: "POST",
    body,
    headers: { "content-type": ct, accept: ct, ...(await signed(url, body)) },
  });
  // Version too new: the SDK refuses, no frames.
  if (conn.status !== undefined) {
    assert.equal(r.status, conn.status, at);
    await r.arrayBuffer();
    return;
  }
  // Wire v5 (`protocol-v1.md` §9.3): a miss ⇒ 409 + `cairn-replay: miss`, empty body; a hit/full ⇒
  // `cairn-replay-cache` exactly as the trace records (absent ⇒ must not be present).
  if (conn.replay?.miss === true) {
    assert.equal(r.status, 409, `${at}: must miss`);
    assert.equal(r.headers.get("cairn-replay"), "miss", at);
    assert.equal((await r.arrayBuffer()).byteLength, 0, `${at}: a miss body must be empty`);
    if (conn.replay.held !== undefined) {
      assert.equal(
        r.headers.get("cairn-replay-held"),
        `${conn.replay.held}:${conn.replay.held_digest}`,
        `${at}: cairn-replay-held`,
      );
    }
    return;
  }
  assert.equal(r.status, 200, at);
  if (conn.replay !== undefined) {
    const cache = r.headers.get("cairn-replay-cache");
    assert.equal(cache === null ? undefined : Number(cache), conn.replay.cache, `${at}: cairn-replay-cache`);
  }
  checkContentType(r.headers.get("content-type") ?? undefined, t.wire_version, at);
  const inbox = new Inbox();
  inbox.push(new Uint8Array(await r.arrayBuffer()));
  inbox.end();
  for (const want of conn.frames.filter((f) => f.from === "sdk")) {
    await expectSdk(inbox, want, at);
    if (want.type === "0x0008") releaseSlow?.();
  }
  assert.deepEqual((await inbox.rest()).map(describe), [], `${at}: the SDK sent extra frames`);
}

async function bidiStream(ep: Endpoint, t: Trace, conn: Connection, at: string): Promise<void> {
  const client = http2.connect(ep.url);
  try {
    const path = `/invoke/${t.handler.service}/${t.handler.name}`;
    const opening = conn.frames.find((f) => f.from === "runtime");
    const stream = client.request({
      ":method": "POST",
      ":path": path,
      "content-type": `application/vnd.cairnflow.invocation.v${t.wire_version}`,
      ...(await signed(`${ep.url}${path}`, opening === undefined ? undefined : fromHex(opening.hex))),
    });
    const inbox = new Inbox();
    const headers = new Promise<http2.IncomingHttpHeaders>((resolve) => stream.on("response", resolve));
    stream.on("data", (c: Buffer) => inbox.push(new Uint8Array(c)));
    stream.on("end", () => inbox.end());
    stream.on("close", () => inbox.end());
    stream.on("error", () => inbox.end());
    // Version too new: the SDK refuses before reading the body, no frames.
    if (conn.status !== undefined) {
      for (const step of runs(conn.frames)) if ("bytes" in step) stream.write(Buffer.from(step.bytes));
      const h = await headers;
      assert.equal(Number(h[":status"]), conn.status, at);
      // The body is a JSON error, not a protocol frame.
      assert.ok(!INVOCATION.test(String(h["content-type"] ?? "").split(";")[0]!.trim()), `${at}: ${h["content-type"]}`);
      stream.end();
      return;
    }

    for (const step of runs(conn.frames)) {
      if ("bytes" in step) {
        stream.write(Buffer.from(step.bytes));
        continue;
      }
      await expectSdk(inbox, step, at);
      // `slowRun`: the closure is held until the first Keepalive arrives (README).
      if (step.type === "0x0008") releaseSlow?.();
    }
    checkContentType((await headers)["content-type"] as string | undefined, t.wire_version, at);
    if (conn.close === "runtime") {
      // The runtime closes its side: the SDK must close too, without another journal frame.
      stream.end();
      assert.deepEqual((await inbox.rest()).map(describe), [], `${at}: the SDK kept sending after the runtime closed`);
    } else {
      assert.deepEqual((await inbox.rest()).map(describe), [], `${at}: the SDK sent extra frames`);
      stream.end();
    }
  } finally {
    // `destroy`, not `close`: a trace diverging midway leaves the stream open, and
    // `close` would wait for it until the test times out.
    client.destroy();
  }
}

/** Negotiation (`protocol-v1.md` §2): the runtime picks the largest version within both ranges. */
async function negotiate(ep: Endpoint, t: Trace): Promise<void> {
  const r = await fetch(`${ep.url}/discover`, {
    headers: { accept: "application/vnd.cairnflow.endpointmanifest.v1+json", ...(await signed(`${ep.url}/discover`)) },
  });
  const m = (await r.json()) as { protocolMode: string; minProtocolVersion: number; maxProtocolVersion: number };
  assert.equal(m.protocolMode, t.mode);
  // The fake runtime speaks [1, wire_version].
  // A version-too-new trace: the SDK is pinned below the version the runtime speaks — no negotiation.
  if (t.sdk_max_protocol_version !== undefined) {
    assert.equal(m.maxProtocolVersion, t.sdk_max_protocol_version, `${t.name}: SDK cap`);
    return;
  }
  const chosen = Math.min(m.maxProtocolVersion, t.wire_version);
  assert.ok(chosen >= Math.max(1, m.minProtocolVersion), `${t.name}: no overlap`);
  assert.equal(chosen, t.wire_version, `${t.name}: negotiated v${chosen}`);
}

/** The final journal: the commands the SDK emitted (beyond the durable prefix) are exactly its command part. */
function checkJournal(t: Trace): void {
  const sent = t.connections
    .filter((c) => !c.verify)
    .flatMap((c) => c.frames)
    .filter((f) => f.from === "sdk" && f.type.startsWith("0x04"));
  const commands = t.journal
    .slice(t.initial_journal_len)
    .filter((e) => e.type.startsWith("0x04"));
  assert.equal(sent.length, commands.length, `${t.name}: number of SDK commands differs from the commands in the journal`);
  sent.forEach((f, i) => {
    const e = commands[i]!;
    assert.equal(f.type, e.type, `${t.name}: command ${i}`);
    if ((e.match ?? "bytes") === "bytes") {
      assert.equal(f.hex.slice(16), e.payload_hex, `${t.name}: payload of command ${i} differs from the journal`);
    }
  });
  // The verify connection replays the whole final journal, in entry order.
  const verify = t.connections.find((c) => c.verify);
  if (verify !== undefined) {
    const replayed = verify.frames.filter((f) => f.from === "runtime").slice(1);
    assert.deepEqual(
      replayed.map((f) => f.hex.slice(16)),
      t.journal.map((e) => e.payload_hex),
      `${t.name}: the verify connection did not replay the journal exactly`,
    );
  }
}

/** Number of times the SDK downloaded a segment through the runner's `fetch` hook (v6 traces). */
let segmentFetches = 0;

async function runTrace(t: Trace, maxWire: number, via: Via = "serve"): Promise<void> {
  // v5 traces: a **fresh** SDK per trace — the cache is keyed by invocation id, and every trace shares the id.
  const own = t.wire_version >= 5;
  let ep = await (own ? freshEndpoint(t.mode, maxWire, via) : endpoint(t.mode, maxWire, via));
  await negotiate(ep, t);
  const realNow = Date.now;
  Date.now = () => t.clock_ms;
  // Wire v6: the SDK downloads segments by `Start.segment_urls` — the runner serves exactly the
  // trace's bytes for those URLs, every other request goes to the real `fetch`.
  const realFetch = globalThis.fetch;
  const served = new Map((t.segments ?? []).map((s) => [s.url, fromHex(s.hex)]));
  if (served.size > 0) {
    globalThis.fetch = (async (input: string | URL | Request, init?: RequestInit) => {
      const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
      const body = served.get(url);
      if (body !== undefined) {
        segmentFetches++;
        return new Response(body as Uint8Array<ArrayBuffer>, { status: 200 });
      }
      return realFetch(input, init);
    }) as typeof fetch;
  }
  releaseSlow = null;
  try {
    for (const [i, conn] of t.connections.entries()) {
      const at = `${t.name} connection ${i}${conn.verify ? " (verify)" : ""}`;
      if (conn.replay?.sdk_restart === true) {
        await ep.close();
        ep = await freshEndpoint(t.mode, maxWire, via);
      }
      if (conn.replay?.stale_sdk === true) {
        // The second replica: received every earlier connection except the last 200 one.
        const prior = t.connections.slice(0, i);
        const last = prior.map((c) => c.replay?.miss !== true).lastIndexOf(true);
        const stale = await freshEndpoint(t.mode, maxWire, via);
        for (const [j, c] of prior.entries()) {
          if (j === last || c.replay?.miss === true) continue;
          await requestResponse(stale, t, c, `${t.name} stale replica, connection ${j}`);
        }
        await ep.close();
        ep = stale;
      }
      if (t.mode === "REQUEST_RESPONSE") await requestResponse(ep, t, conn, at);
      else await bidiStream(ep, t, conn, at);
    }
  } finally {
    Date.now = realNow;
    globalThis.fetch = realFetch;
    if (own) await ep.close();
  }
}

// ─────────────────────────────────────────────────── test

const traces: Trace[] = traceFiles.map((f) => {
  const t = JSON.parse(readFileSync(new URL(`traces/${f}`, ROOT), "utf8")) as Trace;
  assert.equal(`${t.name}.json`, f, `trace name ${t.name} differs from file name ${f}`);
  return t;
});

test("every trace matches trace.schema.json and its journal is self-consistent", () => {
  assert.ok(traces.length > 0, "conformance/traces is empty");
  for (const t of traces) {
    const errors: string[] = [];
    validate(t, schema, t.name, errors);
    assert.deepEqual(errors, [], `${t.name} deviates from the schema`);
    checkJournal(t);
  }
});

test("the trace set covers the two cells of `protocol-v1.md` §10 never checked with a real SDK, and wire 1, 2, 3", () => {
  const cells = new Set(traces.flatMap((t) => t.matrix_cells));
  for (const c of [1, 2, 3, 4]) assert.ok(cells.has(c), `no trace covers cell ${c} of protocol-v1.md §10`);
  const wires = new Set(traces.map((t) => t.wire_version));
  for (const w of [1, 2, 3]) assert.ok(wires.has(w), `no trace at wire v${w}`);
  assert.ok(traces.some((t) => t.connections.some((c) => c.frames.some((f) => f.channel === "side" && f.from === "sdk"))));
  assert.ok(traces.some((t) => t.connections.some((c) => c.frames.some((f) => f.channel === "side" && f.from === "runtime"))));
});

for (const t of traces) {
  // A version-too-new trace: one run with the SDK pinned at the trace's cap (both serve and the Fetch adapter).
  if (t.sdk_max_protocol_version !== undefined) {
    const pin = t.sdk_max_protocol_version;
    test(`trace ${t.name} (${t.mode}, runtime v${t.wire_version}, SDK pinned v${pin})`, async () => {
      await runTrace(t, pin);
    });
    if (t.mode === "REQUEST_RESPONSE") {
      test(`trace ${t.name} — through the Fetch adapter`, async () => {
        await runTrace(t, pin, "fetch");
      });
    }
    continue;
  }
  // The SDK does not yet speak the trace's wire (e.g. v5 before the SDK implemented it).
  const ahead = t.wire_version > MAX_PROTOCOL_VERSION ? `the SDK only speaks up to v${MAX_PROTOCOL_VERSION}` : false;
  test(`trace ${t.name} (${t.mode}, wire v${t.wire_version})`, { skip: ahead }, async () => {
    await runTrace(t, MAX_PROTOCOL_VERSION);
  });
  if (t.wire_version < MAX_PROTOCOL_VERSION) {
    test(`trace ${t.name} — SDK pinned at maxProtocolVersion = ${t.wire_version}`, async () => {
      await runTrace(t, t.wire_version);
    });
  }
  if (t.mode === "REQUEST_RESPONSE") {
    test(`trace ${t.name} — through the Fetch adapter`, { skip: ahead }, async () => {
      await runTrace(t, MAX_PROTOCOL_VERSION, "fetch");
    });
    if (t.wire_version < MAX_PROTOCOL_VERSION) {
      test(`trace ${t.name} — through the Fetch adapter, pinned maxProtocolVersion = ${t.wire_version}`, async () => {
        await runTrace(t, t.wire_version, "fetch");
      });
    }
  }
}

test("wire v6 traces: the SDK really downloads segments through the Start.segment_urls URLs", () => {
  // The SDK's segment cache belongs to the process: only the first time per endpoint downloads.
  if (traces.some((t) => (t.segments ?? []).length > 0)) assert.ok(segmentFetches > 0, "no segment download at all");
});

test("the REQUEST_RESPONSE matrix through the Fetch adapter is not empty", () => {
  assert.ok(traces.some((t) => t.mode === "REQUEST_RESPONSE"), "no REQUEST_RESPONSE trace to run through the adapter");
});

// ─────────────────────────────── suspension vectors

interface SuspensionVector {
  readonly name: string;
  readonly tree: SuspensionTree;
  readonly hex: string;
  readonly states: ReadonlyArray<{
    readonly completions: readonly number[];
    readonly signals: readonly number[];
    readonly names: readonly string[];
    readonly satisfied: boolean;
  }>;
}

/**
 * The same vector file as `crates/cairn-runtime/tests/suspension_vectors.rs`: the
 * SDK encodes each tree to **exactly** the bytes in the file (the Rust side decodes
 * those very bytes), and the SDK's satisfaction rule reaches the same verdict as
 * the runtime on every combination of leaves.
 */
test("suspension tree — the SDK encodes the exact bytes, its satisfaction rule matches the runtime", () => {
  const doc = JSON.parse(readFileSync(new URL("suspension-vectors.json", ROOT), "utf8")) as {
    vectors: SuspensionVector[];
  };
  assert.ok(doc.vectors.length >= 10);
  const hex = (b: Uint8Array) => [...b].map((x) => x.toString(16).padStart(2, "0")).join("");
  let checked = 0;
  for (const v of doc.vectors) {
    assert.equal(hex(encodeSuspensionSpec({ tree: v.tree })), v.hex, `${v.name}: bytes differ`);
    for (const s of v.states) {
      const got = treeSatisfied(
        v.tree,
        (c) => s.completions.includes(c),
        (i) => s.signals.includes(i),
        (n) => s.names.includes(n),
      );
      assert.equal(got, s.satisfied, `${v.name}: the SDK says ${got} for ${JSON.stringify(s)}`);
      checked++;
    }
  }
  assert.ok(checked > 70);
});
